command_result.command:
cd /app && for t in all build/lib/libqs.a build/bin/colstat build/bin/qcalc check install; do for i in 1 2 3; do make clean >/dev/null; make -j8 $t DESTDIR=/tmp/st2 >/tmp/out.txt 2>&1 || { echo FAIL $t; tail -5 /tmp/out.txt; }; done; echo done $t; done; ls build; ls build/bin build/lib; find . -name '*.o' -not -path './build/*'; 
cat > /tmp/t.c <<'EOF'
#include <qs/qs.h>
#include <stdio.h>
int main(void){double v; qs_eval("2^10",&v); printf("%s %g\n",QS_VERSION,v); return 0;}
EOF
gcc -std=c11 -I/tmp/stage/usr/include /tmp/t.c /tmp/stage/usr/lib/libqs.a -lm -o /tmp/t && /tmp/t
